import {wallSegments,wallPoint,projectToWall} from './room-geometry.mjs';
import {validate,wallLength,footprint} from './room-model.mjs';
export function wallPosition(p,wall,t){return wallPoint(p,wall,t).slice(0,2);}
export function doorSwing(p,o){const end=o.hinge==='end',at=o.offset+(end?o.width:0),hinge=wallPosition(p,o.wall,at),tangent=wallSegments(p)[o.wall].tangent,normal=wallSegments(p)[o.wall].normal,sign=end?-1:1,out=o.swing==='out'?-1:1;const arc=[];for(let i=0;i<=24;i++){const a=i*Math.PI/48;arc.push([hinge[0]+o.width*(tangent[0]*sign*Math.cos(a)+normal[0]*out*Math.sin(a)),hinge[1]+o.width*(tangent[1]*sign*Math.cos(a)+normal[1]*out*Math.sin(a))]);}return {hinge,arc,tip:arc.at(-1)};}
export function moveOpening(p,index,x,y,grabFraction=.5){const next=structuredClone(p),o=next.openings[index];if(!o)throw Error('Проём не найден');const segments=wallSegments(p),projected=segments.map(s=>projectToWall(s,x,y)),distances=projected.map(v=>v.distance),closest=distances.indexOf(Math.min(...distances));if(distances[closest]<.6&&distances[o.wall]>distances[closest]+.12)o.wall=closest;const max=wallLength(p,o.wall)-o.width;if(max<0)throw Error('Проём шире выбранной стены');const t=projected[o.wall].t;o.offset=Math.max(0,Math.min(max,Math.round((t-o.width*grabFraction)*100)/100));return validate(next);}

export function doorHitsFurniture(p,o,f){const {hinge}=doorSwing(p,o),t=wallSegments(p)[o.wall].tangent,n=wallSegments(p)[o.wall].normal,hs=o.hinge==='end'?-1:1,sw=o.swing==='out'?-1:1,{w,d}=footprint(f);const corners=[[f.x,f.y],[f.x+w,f.y],[f.x+w,f.y+d],[f.x,f.y+d]],us=corners.map(([x,y])=>((x-hinge[0])*t[0]+(y-hinge[1])*t[1])*hs),vs=corners.map(([x,y])=>((x-hinge[0])*n[0]+(y-hinge[1])*n[1])*sw);if(Math.max(...us)<=0||Math.max(...vs)<=0)return false;const u=Math.max(0,Math.min(...us)),v=Math.max(0,Math.min(...vs));return u*u+v*v<o.width*o.width-1e-8;}
